import{_ as a,o as d,c as e,a3 as r}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"重写与渐进式迁移","description":"","frontmatter":{"title":"重写与渐进式迁移","outline":[2,3],"article":{"type":"decision","structure":"decision"}},"headers":[],"relativePath":"frontend/decisions/delivery/rewrite-vs-migrate.md","filePath":"frontend/decisions/delivery/rewrite-vs-migrate.md","lastUpdated":1785589115000}'),i={name:"frontend/decisions/delivery/rewrite-vs-migrate.md"};function l(o,t,h,n,s,c){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="重写与渐进式迁移" tabindex="-1">重写与渐进式迁移 <a class="header-anchor" href="#重写与渐进式迁移" aria-label="Permalink to &quot;重写与渐进式迁移&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>重写承诺一个干净目标状态，渐进式迁移用较长双轨期换取连续反馈。两者都可能成功，也都可能失败：重写常低估隐含业务行为和切换，渐进迁移常忘记删除旧系统而永久支付双份成本。</p><h2 id="_1-决策背景" tabindex="-1">1. 决策背景 <a class="header-anchor" href="#_1-决策背景" aria-label="Permalink to &quot;1. 决策背景&quot;">​</a></h2><p>遗留系统的痛苦可能来自架构、停止维护依赖、缺少测试、产品规则混乱或组织所有权。只有确认根因，才能判断换技术是否真正解决问题。</p><p>“旧代码很差”不是可验收目标。应写清需要改善的业务结果，例如发布周期、故障率、支持期限、浏览器性能和人才风险。</p><h2 id="_2-硬约束与评价标准" tabindex="-1">2. 硬约束与评价标准 <a class="header-anchor" href="#_2-硬约束与评价标准" aria-label="Permalink to &quot;2. 硬约束与评价标准&quot;">​</a></h2><h3 id="_2-1-迁移硬约束" tabindex="-1">2.1 迁移硬约束 <a class="header-anchor" href="#_2-1-迁移硬约束" aria-label="Permalink to &quot;2.1 迁移硬约束&quot;">​</a></h3><ul><li>核心业务、审计和数据语义在迁移期间保持正确；</li><li>用户会话、深链、权限和外部集成有明确兼容策略；</li><li>任何批次都有回滚或旁路，数据库不可逆变更单独治理；</li><li>旧系统有冻结、支持和最终退休负责人；</li><li>迁移预算不挤占必须持续交付的业务承诺。</li></ul><h3 id="_2-2-评价维度" tabindex="-1">2.2 评价维度 <a class="header-anchor" href="#_2-2-评价维度" aria-label="Permalink to &quot;2.2 评价维度&quot;">​</a></h3><p>比较隐含需求可发现性、测试基线、系统耦合、切片能力、双轨成本、一次切换风险、团队容量、业务窗口、回滚、预计寿命和可量化收益。</p><h2 id="_3-候选方案" tabindex="-1">3. 候选方案 <a class="header-anchor" href="#_3-候选方案" aria-label="Permalink to &quot;3. 候选方案&quot;">​</a></h2><h3 id="_3-1-维持、修复与隔离" tabindex="-1">3.1 维持、修复与隔离 <a class="header-anchor" href="#_3-1-维持、修复与隔离" aria-label="Permalink to &quot;3.1 维持、修复与隔离&quot;">​</a></h3><p>继续运行旧系统，只修复高风险问题，通过边界隔离并限制新增能力。适合稳定、低变化、迁移收益不足的系统，但必须有支持期限，不能成为默认拖延。</p><h3 id="_3-2-原地渐进升级" tabindex="-1">3.2 原地渐进升级 <a class="header-anchor" href="#_3-2-原地渐进升级" aria-label="Permalink to &quot;3.2 原地渐进升级&quot;">​</a></h3><p>在同一应用内逐步升级依赖、模块和页面，适合路由或领域可切片且需要持续交付的系统。代价是兼容层、双测试和较长治理周期。</p><h3 id="_3-3-绞杀式替换" tabindex="-1">3.3 绞杀式替换 <a class="header-anchor" href="#_3-3-绞杀式替换" aria-label="Permalink to &quot;3.3 绞杀式替换&quot;">​</a></h3><p>在外壳、路由或服务边界旁建立新实现，按用户旅程导流，逐步缩小旧系统。适合可以清楚分流和独立部署的场景；需要处理身份、导航、监控和数据一致性。</p><h3 id="_3-4-全量重写与切换" tabindex="-1">3.4 全量重写与切换 <a class="header-anchor" href="#_3-4-全量重写与切换" aria-label="Permalink to &quot;3.4 全量重写与切换&quot;">​</a></h3><p>新旧并行开发，到验收后一次或少量批次切换。适合范围小、规范完整、外部窗口固定或旧技术无法共存的系统。最大风险是长期没有真实用户反馈和功能追赶。</p><h2 id="_4-关键维度对比" tabindex="-1">4. 关键维度对比 <a class="header-anchor" href="#_4-关键维度对比" aria-label="Permalink to &quot;4. 关键维度对比&quot;">​</a></h2><p>案例是 Vue 2 运营系统：140 个路由、8 年历史、每周 30 个需求、关键规则缺少文档、E2E 只覆盖 12 条旅程；Vue 2 构建依赖已停止组织内支持，但系统不能停更。</p><table tabindex="0"><thead><tr><th>维度</th><th>维持隔离</th><th>原地渐进</th><th>绞杀替换</th><th>全量重写</th></tr></thead><tbody><tr><td>持续业务交付</td><td>高</td><td>高</td><td>高</td><td>低至中</td></tr><tr><td>隐含规则发现</td><td>不改善</td><td>随迁移发现</td><td>随流量发现</td><td>切换前难发现</td></tr><tr><td>双轨成本</td><td>低</td><td>中</td><td>高</td><td>高</td></tr><tr><td>首次真实反馈</td><td>无</td><td>早</td><td>早</td><td>晚</td></tr><tr><td>最终一致目标</td><td>无</td><td>中</td><td>高</td><td>高</td></tr><tr><td>切换风险</td><td>持续老化</td><td>小批次</td><td>小批次</td><td>最大</td></tr></tbody></table><h2 id="_5-场景化推荐结论" tabindex="-1">5. 场景化推荐结论 <a class="header-anchor" href="#_5-场景化推荐结论" aria-label="Permalink to &quot;5. 场景化推荐结论&quot;">​</a></h2><p>推荐“路由级绞杀 + 原地基础治理”的组合：先在旧系统补关键旅程、错误监控和统一身份外壳；新 Vue 3 应用按订单查询、导出中心、库存维护等完整路由接管流量；共享 API 契约，不共享页面 Store 和组件内部实现。</p><p>首个试点选择业务中等、边界完整的导出中心，不选最简单静态页，也不选支付高风险路径。试点门槛是错误率不高于旧版、交付周期增加不超过 15%、回滚在 10 分钟内完成。</p><p>不承诺像素和所有偶然行为完全复制。产品、客服和审计共同确认“必须保持、允许改变、明确删除”的行为清单。</p><h2 id="_6-引入后的后果" tabindex="-1">6. 引入后的后果 <a class="header-anchor" href="#_6-引入后的后果" aria-label="Permalink to &quot;6. 引入后的后果&quot;">​</a></h2><p>团队能持续获得真实反馈并分批回滚，同时承担双构建、双监控、导航外壳和兼容 API。迁移预算必须包含旧代码删除；每接管一个路由，就关闭旧入口、归档数据和移除对应依赖。</p><p>迁移期间新需求默认只进入新实现；确需同时修改时记录为双写成本。若业务追赶使旧代码从未减少，应暂停扩张并重新评估。</p><p>退出迁移项目的方式也要明确：试点失败时可恢复旧路由并保留已提取测试；不允许为了沉没成本继续批量迁移。</p><h2 id="_7-不适用场景" tabindex="-1">7. 不适用场景 <a class="header-anchor" href="#_7-不适用场景" aria-label="Permalink to &quot;7. 不适用场景&quot;">​</a></h2><ul><li>小而稳定、即将下线的系统可能只需隔离和支持。</li><li>无法按路由、数据或用户切片且存在固定切换窗口时，渐进迁移未必可行。</li><li>重写不能自动消除未澄清的业务复杂度。</li><li>不要把所有技术升级、设计改版和业务重构放进同一迁移。</li><li>没有旧系统退休指标的“渐进迁移”容易永久双轨。</li></ul><h2 id="_8-填写完成的决策记录" tabindex="-1">8. 填写完成的决策记录 <a class="header-anchor" href="#_8-填写完成的决策记录" aria-label="Permalink to &quot;8. 填写完成的决策记录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>问题</td><td>140 路由 Vue 2 系统如何退出停止支持的技术栈</td></tr><tr><td>硬约束</td><td>每周继续发布；审计行为保持；10 分钟回滚；18 个月支持期限</td></tr><tr><td>候选</td><td>维持隔离、原地升级、绞杀替换、全量重写</td></tr><tr><td>决定</td><td>路由级绞杀，配合旧系统基础治理</td></tr><tr><td>首个切片</td><td>导出中心完整旅程</td></tr><tr><td>接受代价</td><td>双构建、身份外壳、兼容 API 和迁移团队</td></tr><tr><td>停止条件</td><td>试点错误率高 20% 或交付周期恶化 15% 且两轮无法修正</td></tr><tr><td>成功指标</td><td>旧路由数、旧依赖数、双写需求、错误率、回滚时间、交付周期</td></tr></tbody></table><h2 id="_9-复查条件" tabindex="-1">9. 复查条件 <a class="header-anchor" href="#_9-复查条件" aria-label="Permalink to &quot;9. 复查条件&quot;">​</a></h2><p>试点门槛失败、业务容量减少 30%、旧系统获得新的官方支持、切片需要持续跨系统事务，或旧路由连续两月没有下降时复查。复查可以缩小范围、改变切片边界、暂时维持，或在条件成熟时转为集中切换。</p>',37)])])}const p=a(i,[["render",l]]);export{u as __pageData,p as default};
